"use client";
import { useState } from "react";
import { smoothShadow } from "@/components/application/selene/smooth-shadows";

export default function SmoothShadowsDemo() {
  const [size, setSize] = useState(8);
  const [intensity, setIntensity] = useState(4);
  const shadow = smoothShadow({ size, intensity, ring: true, hairline: true });
  const slider = (label: string, value: number, set: (v: number) => void, max: number) => (
    <label style={{ display: "grid", gridTemplateColumns: "72px 1fr 28px", alignItems: "center", gap: 10, fontSize: 13 }}>
      {label}
      <input type="range" min={1} max={max} value={value} onChange={(e) => set(Number(e.target.value))} />
      <span style={{ textAlign: "right", color: "light-dark(#71717a, #a1a1aa)", fontVariantNumeric: "tabular-nums" }}>{value}</span>
    </label>
  );
  return (
    <div style={{ display: "grid", gap: 28, justifyItems: "center", width: "100%", maxWidth: 340, padding: "8px 0", color: "light-dark(#1a1a1c, #ececee)" }}>
      <div style={{ display: "flex", alignItems: "flex-start", gap: 18 }}>
        <div style={{ width: 132, padding: 8, borderRadius: 14, background: "light-dark(#fff, #1c1c1f)", boxShadow: shadow }}>
          <div style={{ height: 56, borderRadius: 8, background: "light-dark(linear-gradient(135deg, #e9e6ff, #f4f1ff), linear-gradient(135deg, #2e2a4a, #3a3460))" }} />
          <div style={{ padding: "8px 4px 2px", fontSize: 12, fontWeight: 600 }}>Weekly report</div>
          <div style={{ padding: "0 4px 2px", fontSize: 11, color: "light-dark(#71717a, #a1a1aa)" }}>Updated 2h ago</div>
        </div>
        <div style={{ display: "grid", gap: 16 }}>
          <button type="button" style={{ height: 34, padding: "0 14px", border: 0, borderRadius: 10, color: "inherit", background: "light-dark(#fff, #1c1c1f)", font: "inherit", fontSize: 13, fontWeight: 600, boxShadow: shadow, cursor: "pointer" }}>
            Download
          </button>
          <div role="menu" style={{ display: "grid", width: 132, padding: 4, borderRadius: 12, background: "light-dark(#fff, #1c1c1f)", boxShadow: shadow, fontSize: 12 }}>
            {["Rename", "Duplicate", "Move to…"].map((item, i) => (
              <span key={item} role="menuitem" style={{ padding: "6px 8px", borderRadius: 8, background: i === 0 ? "light-dark(#f4f4f5, #2a2a2e)" : undefined }}>
                {item}
              </span>
            ))}
          </div>
        </div>
      </div>
      <div style={{ display: "grid", gap: 8, width: "100%" }}>
        {slider("Size", size, setSize, 32)}
        {slider("Intensity", intensity, setIntensity, 20)}
      </div>
    </div>
  );
}

